entries[384688] = { ["name"] = "Draconium Deposit", ["text"] = "5 yd range\n3.2 sec cast\nDraconium Deposits are a rare find upon the Dragon Isles, but they are more often spotted in rugged or hard to reach locations." }
entries[384689] = { ["name"] = "Divide and Conquer", ["text"] = "[ Breath of Eons / Deep Breath] forms curtains of fire, preventing line of sight to enemies outside its walls and burning enemies who walk through them for (480% of Spell Power) Fire damage. Lasts 6 sec." }
entries[384690] = { ["name"] = "Molten Draconium Deposit", ["text"] = "5 yd range\n3.2 sec cast\nDraconium Deposits are a rare find upon the Dragon Isles, but they are more often spotted in rugged or hard to reach locations.\n\nThey are sometimes enveloped in flames, particularly in geologically active regions. Its unbearable heat often deters novice miners from harvesting its abundance of Rousing Fire.\n\nMiners specialized in Molten nodes will gain the following effect when mining:\n\nMolten Fury :\nEnvelops you in flame which causes your attackers to suffer 1721 Fire damage. Lasts 2 min." }
entries[384691] = { ["name"] = "Divide and Conquer", ["text"] = "100 yd range\nInstant\nDeep Breath forms a wall of fire for 8 sec, preventing line of sight through the wall. Enemies who cross through the wall are damaged for 1." }
entries[384692] = { ["name"] = "Serevite Deposit", ["text"] = "5 yd range\n2.5 sec cast\nSerevite is the most common ore found across the Dragon Isles. Though it is often found in mountainous regions, it is also revealed around flowing bodies of water.\nProfession:\nMining (1)" }
entries[384693] = { ["name"] = "Rich Draconium Deposit", ["text"] = "5 yd range\n5.3 sec cast\nDraconium Deposits are a rare find upon the Dragon Isles, but they are more often spotted in rugged or hard to reach locations.\n\nRich deposits are particularly dense with ore, sure to delight any miner to stumble upon one." }
entries[384694] = { ["name"] = "Awakened Chill", ["text"] = "Instant 3 min cooldown\nCast an Awakening Chill that deals between 0-4 Frost damage in a cone and slowing enemies by 50% for 4 sec. Damage dealt is determined by the top-most card of the deck.\n\nEquip: Periodically shuffle the deck while in combat." }
